const storageKey='cairn-design-preview-v1';
let data;
try { const raw=localStorage.getItem(storageKey); data=raw?{...structuredClone(initial),...JSON.parse(raw)}:structuredClone(initial); } catch {data=structuredClone(initial);}
let storageConfirmed=false, storageFailed=false;
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(data));storageConfirmed=true;storageFailed=false;return true;}catch{storageConfirmed=false;storageFailed=true;return false;}}
persist();
let page='home', libTab='all', homeTab='today', taskTab='list', settingTab='appearance', filter='', readingFilter='all', groupFilter='all', taskScope='all', selectedTask=null, selectedNote='n1', selectedArticle='a1', selectedCollection=null, state='normal', captureType='memo', forcedMobile=false, composing=false, drawer=false, lastFocus=null, savedSelection=null, noteTimer=null, toastTimer=null, zoom=80, noteStatus='saved';
const titles={home:'工作台',library:'资料库',notes:'笔记',note:'笔记',reader:'资料库',tasks:'待办',canvas:'构思画布',settings:'设置',favorites:'收藏夹',trash:'垃圾箱'};
const shell=$('#shell'), modal=$('#modal');
const isMobile=()=>forcedMobile||shell.clientWidth<768;
const readOnly=()=>state==='readonly';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function saveFeedback(){ if(persist()){toast('已保存到此浏览器');}else{toast('无法保存到此浏览器，请复制内容保留');}renderBanner();}
function setTheme(mode){data.theme=mode;const dark=mode==='dark'||(mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-select').value=mode;persist();}
setTheme(data.theme);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(data.theme==='system')setTheme('system');});
function sanitize(html){const tpl=document.createElement('template');tpl.innerHTML=html;const allowed=['P','H2','H3','UL','OL','LI','STRONG','EM','B','I','BLOCKQUOTE','BR'];const walk=node=>{[...node.children].forEach(child=>{if(!allowed.includes(child.tagName)){child.replaceWith(document.createTextNode(child.textContent));}else{[...child.attributes].forEach(a=>child.removeAttribute(a.name));walk(child);}});};walk(tpl.content);return tpl.innerHTML;}
function navigate(next,opts={}){flushNote();page=next;filter='';if(opts.libTab)libTab=opts.libTab;if(opts.note)selectedNote=opts.note;if(opts.article)selectedArticle=opts.article;if(opts.task)selectedTask=opts.task;else if(next!=='tasks')selectedTask=null;selectedCollection=opts.collection||null;closeDrawer();render();$('#main').scrollTop=0;history.replaceState(null,'','#'+next);}
function flushNote(){if(noteTimer){clearTimeout(noteTimer);noteTimer=null;persist();noteStatus=storageFailed?'error':'saved';}}
function renderSidebar(){
 const navs=[['home','Home','工作台'],['library','Library','资料库'],['favorites','Star','收藏夹'],['notes','FileText','笔记'],['canvas','LayoutGrid','构思画布'],['tasks','ListChecks','待办']];
 $('#sidebar').innerHTML=`<div class="brand"><a href="#home" data-page="home" class="brand-word"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i></span>Cairn</a>${ib('X','关闭导航','drawer-close','drawer-close')}</div><button class="nav-search" data-action="search">${icon('Search')}<span>搜索</span><kbd>⌘ K</kbd></button><nav>${navs.map(([key,ico,label])=>`<button class="nav-link ${page===key||(key==='notes'&&page==='note')||(key==='library'&&page==='reader')?'active':''}" data-page="${key}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`).join('')}</nav><div class="nav-section"><span>最近笔记</span><button data-action="new-note" aria-label="新建笔记">${icon('Plus')}</button></div>${data.notes.slice(0,3).map(n=>`<button class="sub-link" data-note="${esc(n.id)}">${icon('FileText')}<span>${esc(n.title)}</span></button>`).join('')}<div class="nav-section"><span>我的集合</span><button data-action="new-collection" aria-label="新建集合">${icon('Plus')}</button></div>${data.collections.slice(0,3).map(c=>`<button class="sub-link" data-collection="${esc(c.id)}">${icon('Folder')}<span>${esc(c.title)}</span></button>`).join('')}<div class="side-spacer"></div><button class="nav-link ${page==='trash'?'active':''}" data-page="trash">${icon('Trash2')}<span>垃圾箱</span></button><button class="nav-link ${page==='settings'?'active':''}" data-page="settings">${icon('Settings')}<span>设置</span></button><div class="account"><span class="avatar">K</span><div>我的空间<small>个人账户</small></div>${ib('MoreHorizontal','账户选项','account')}</div>`;
}
function renderTop(){const n=data.notes.find(n=>n.id===selectedNote);const detail=page==='note'||page==='reader';const status=noteStatus==='saving'?'正在保存…':noteStatus==='error'?'尚未保存':state==='offline'?'待同步':state==='conflict'?'存在冲突':storageFailed?'尚未保存':'已保存到本机';
 $('#topbar').innerHTML=`<div class="topbar-left">${ib(detail?'ChevronLeft':'Menu',detail?'返回列表':'打开导航',detail?'back':'drawer-open',detail?'':'desktop-menu')}<span class="crumb-home">我的空间</span><span class="crumb-separator">/</span><span>${detail?esc(page==='note'?n?.title||'无标题':'阅读'):titles[page]}</span></div><div class="topbar-right">${page==='note'?`<span class="save-status ${noteStatus==='error'?'sync-error':''}" role="status">${icon(noteStatus==='saving'?'Clock':'Check')}${status}</span>${ib('MessageSquare','评论','comments')}`:''}${page==='reader'?`<span class="save-status">已读 38%</span>${ib('Star','收藏文章','favorite')}`:''}${ib('Search','搜索全部内容','search','topbar-search')}${ib('Plus','新建','new','topbar-new')}${ib('MoreHorizontal','更多选项','page-more')}</div>`;
 shell.classList.toggle('detail',detail||Boolean(selectedTask));
}
function renderBanner(){const b=$('#state-banner');let text='',cls=state,act='normal',label='';if(storageFailed){cls='error';text='此浏览器无法保存更改，请复制内容保留。';act='export';label='导出内容';}else if(state==='offline'){text=storageConfirmed?'离线 · 更改已保存在此设备，尚未同步':'离线 · 尚未同步';label='重新连接';}else if(state==='readonly'){text='你正在查看只读内容';label='返回可编辑状态';}else if(state==='conflict'){text='另一处有新版本，请比较后继续。';label='比较版本';act='resolve';}else if(state==='error'){text='部分内容暂时无法加载，已有内容仍可查看。';label='重试';}b.innerHTML=text?`<div class="state-banner ${cls}"><span>${text}</span><button data-action="${act}">${label}</button></div>`:'';}
function tabs(items,current,attr){return `<div class="tabs" role="tablist">${items.map(([id,label])=>`<button role="tab" aria-selected="${current===id}" tabindex="${current===id?0:-1}" class="${current===id?'active':''}" data-${attr}="${id}">${label}</button>`).join('')}</div>`;}
function searchField(placeholder){return `<label class="search-field">${icon('Search')}<input id="page-search" type="search" value="${esc(filter)}" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}"></label>`;}
function empty(title='这里还没有内容',desc='把值得留下的资料和想法，慢慢放在这里。',action='new',label='添加第一条'){return `<div class="empty"><div>${icon('FileText')}<h2>${title}</h2><p>${desc}</p>${button(label,action,'outline','Plus')}</div></div>`;}
function filtered(items){if(state==='empty')return [];return items.filter(x=>(x.title+' '+(x.tag||'')+' '+(x.group||'')).toLowerCase().includes(filter.toLowerCase()));}
function taskRows(items){return items.map(t=>`<div class="task-row"><button class="check ${t.done?'checked':''}" role="checkbox" aria-checked="${t.done}" aria-label="${esc((t.done?'标为未完成：':'完成：')+t.title)}" data-task-check="${t.id}" ${readOnly()?'disabled':''}>${t.done?icon('Check'):''}</button><button class="task-copy ${t.done?'done':''}" data-task="${t.id}"><span>${esc(t.title)}</span><small>${esc(t.list)}${t.sub?' · '+esc(t.sub):''}</small></button><span class="date ${t.date==='今天'&&!t.done?'due':''}">${esc(t.date)}</span></div>`).join('');}
function materialRows(items){return items.map(m=>`<div class="content-row"><div class="object-icon">${icon(m.type==='reading'?'Link':m.type==='files'?'File':'FileText')}</div><button class="row-open" data-material="${m.id}"><strong>${esc(m.type==='memos'?m.title.slice(0,35):m.title)}</strong><div class="row-meta"><span>${esc(m.source)}</span><span>·</span><span>${esc(m.meta)}</span>${m.tag?`<span class="chip">${esc(m.tag)}</span>`:''}</div>${libTab==='reading'?`<p>${esc(m.desc)}</p>`:''}</button><div class="row-actions">${m.status?`<span class="chip">${esc(m.status)}</span>`:''}${ib('MoreHorizontal','资料选项','material-more:'+m.id,'reveal')}</div></div>`).join('');}
function capture(){return `<form class="composer" id="capture-form"><textarea id="capture-input" aria-label="快速记录" placeholder="记下一个想法，或粘贴一个链接…" rows="2" ${readOnly()?'disabled':''}></textarea><div class="composer-bottom"><div class="capture-types" aria-label="记录类型">${[['memo','速记'],['note','笔记'],['task','待办']].map(([id,label])=>`<button type="button" data-capture="${id}" aria-pressed="${captureType===id}" class="${captureType===id?'active':''}">${label}</button>`).join('')}</div><div class="inline"><span class="capture-note">⌘ Enter 保存</span><button class="btn primary" type="submit" aria-label="保存记录" ${readOnly()?'disabled':''}>${icon('ArrowUp')}</button></div></div></form>`;}
function home(){
 const homeTabs=`<div class="home-tabs tabs" role="tablist">${[['today','今天'],['review','回顾'],['stats','统计']].map(([id,label])=>`<button data-home-tab="${id}" role="tab" aria-selected="${homeTab===id}" tabindex="${homeTab===id?0:-1}" class="${homeTab===id?'active':''}">${label}</button>`).join('')}</div>`;
 if(homeTab==='review')return `<div class="page"><div class="page-head"><h1>日历回顾</h1>${homeTabs}</div><div class="toolbar"><span class="muted">2026 年 10 月</span>${button('选择日期','pick-date','outline','Calendar')}</div><div class="timeline"><div class="timeline-entry"><small>今天 · 10 月 15 日</small><p>完成了「清理收集箱」</p>${button('查看待办','go-tasks')}</div><div class="timeline-entry"><small>10 月 14 日</small><p>留下了一篇笔记「让知识有一个去处」</p>${button('打开笔记','open-first-note')}</div><div class="timeline-entry"><small>10 月 13 日</small><p>收藏了「把注意力还给重要的事」</p>${button('继续阅读','open-first-article')}</div></div></div>`;
 if(homeTab==='stats')return `<div class="page"><div class="page-head"><h1>阅读与行动</h1>${homeTabs}</div><div class="toolbar"><p class="muted">最近 7 天</p>${button('更改范围','stats-range','outline','Calendar')}</div><div class="stat-strip"><div class="stat"><small>阅读完成</small><strong>12</strong><small>比上周多 3 篇</small></div><div class="stat"><small>留下笔记</small><strong>${data.notes.length+5}</strong><small>每一次思考都有迹可循</small></div><div class="stat"><small>完成待办</small><strong>${data.tasks.filter(t=>t.done).length+17}</strong><small>一步一步向前</small></div></div><h2>本周阅读</h2><div class="chart" role="img" aria-label="周一至周日阅读篇数：2、4、3、5、2、6、4">${[40,70,55,85,40,100,70].map((h,i)=>`<div class="bar" style="height:${h}%"><span>${['一','二','三','四','五','六','日'][i]}</span></div>`).join('')}</div>${button('查看数据明细','stats-table','ghost','FileText')}</div>`;
 return `<div class="page"><div class="page-head home-head"><div><p class="eyebrow">10 月 15 日，星期四</p><h1 class="greeting">给想法一点空间。</h1><p class="greeting-sub">从一条记录开始，慢慢找回自己的节奏。</p></div><div class="head-actions">${homeTabs}</div></div>${capture()}<div class="columns"><section><div class="section-head"><h2>今天要做</h2><button class="text-button" data-page="tasks">全部待办 ${icon('ChevronRight')}</button></div>${state==='empty'?empty('今天还没有安排','留一点空间，也可以从一个小行动开始。','new-task','添加任务'):taskRows(data.tasks.filter(t=>!t.done).slice(0,3))}${button('添加任务','new-task','ghost','Plus')}</section><section><div class="section-head"><h2>接着上次</h2><button class="text-button" data-page="library">打开资料库 ${icon('ChevronRight')}</button></div>${state==='empty'?'<p class="small-summary">开始阅读后，可以从这里继续。</p>':`<button class="continue-row" data-material="a1"><span class="continue-icon">${icon('FileText')}</span><span class="continue-copy"><strong>把注意力还给重要的事</strong><small>阅读到 38% · 还剩 5 分钟</small><span class="progress"><span></span></span></span>${icon('ChevronRight')}</button><button class="continue-row" data-note="n1"><span class="continue-icon">${icon('FileText')}</span><span class="continue-copy"><strong>${esc(data.notes[0].title)}</strong><small>笔记 · 今天 10:42</small></span>${icon('ChevronRight')}</button>`}</section></div><section><div class="section-head"><h2>最近留下的</h2>${searchField('搜索最近资料')}</div>${materialRows(filtered(data.materials).slice(0,4))||empty(filter?'没有找到相关资料':'还没有资料',filter?'试试更短的关键词，或清除搜索。':'粘贴一个链接，把阅读留给合适的时间。',filter?'clear-search':'new',filter?'清除搜索':'添加资料')}</section></div>`;
}
function library(){
 let items=filtered(data.materials).filter(m=>libTab==='all'||m.type===libTab);if(libTab==='reading'&&readingFilter!=='all')items=items.filter(m=>m.status===readingFilter);
 if(selectedCollection){const c=data.collections.find(c=>c.id===selectedCollection);return `<div class="page"><div class="page-head"><div class="inline">${ib('ChevronLeft','返回集合','collection-back')}<h1>${esc(c?.title||'集合')}</h1></div>${button('添加资料','collection-add','outline','Plus')}</div><p class="small-summary">${esc(c?.desc||'把相关资料放在一起。')}</p><div class="toolbar"><span class="muted">集合中的资料</span>${button('生成整理稿','collection-digest','outline','FileText')}</div>${materialRows(filtered(data.materials).slice(0,c?.count||3))||empty()}</div>`;}
 let content='';
 if(libTab==='collections'){content=filtered(data.collections).map(c=>`<div class="collection-row"><div class="collection-tile">${icon('Folder')}</div><button data-collection="${c.id}"><strong>${esc(c.title)}</strong><small>${esc(c.desc)} · ${c.count} 条资料</small></button>${ib('MoreHorizontal','集合选项','collection-more:'+c.id)}</div>`).join('')||empty('还没有集合','把围绕同一个问题的资料，放在一起。','new-collection','新建集合');}
 else if(libTab==='memos'){content=items.map(m=>`<article class="memo-entry"><div class="row-meta"><span>${esc(m.meta)}</span>${ib('MoreHorizontal','速记选项','material-more:'+m.id)}</div><p class="memo-body">${esc(m.title)}</p><span class="chip"># ${esc(m.tag||'随想')}</span></article>`).join('')||empty('留下一点当下的想法','不必完整，先写下来就好。','focus-capture','写一条速记');}
 else content=materialRows(items)||empty(filter?'没有找到相关资料':'这里还没有资料',filter?'试试其他关键词，或清除筛选。':'把值得留下的资料放到这里。',filter?'clear-search':'new',filter?'清除搜索':'添加资料');
 return `<div class="page"><div class="page-head"><h1>资料库</h1><div class="head-actions">${searchField('搜索资料库')}${button(libTab==='collections'?'新建集合':libTab==='files'?'导入文件':'添加资料',libTab==='collections'?'new-collection':libTab==='files'?'file-import':'new','primary','Plus')}</div></div>${tabs([['all','全部'],['reading','文章'],['files','文件'],['memos','速记'],['collections','集合']],libTab,'lib-tab')}${libTab==='memos'?capture():''}<div class="toolbar"><div class="toolbar-left">${libTab==='reading'?`<div class="scope-select">${[['all','全部'],['未读','未读'],['在读','在读'],['已读','已读']].map(([id,label])=>`<button class="${readingFilter===id?'active':''}" data-reading-filter="${id}">${label}</button>`).join('')}</div>`:button('标签','tag-filter','ghost','Tag')}</div>${button('最近添加','sort','ghost','ChevronDown')}</div><div class="mobile-page-search">${searchField('搜索资料库')}</div>${content}</div>`;
}
function notes(){const ns=filtered(data.notes).filter(n=>groupFilter==='all'||n.group===groupFilter);return `<div class="page"><div class="page-head"><h1>笔记</h1><div class="head-actions">${searchField('搜索笔记')}${button('新建笔记','new-note','primary','Plus')}</div></div>${tabs([['all','全部笔记'],['个人思考','个人思考'],['工作','工作'],['生活','生活']],groupFilter,'group')}<div class="toolbar"><div class="toolbar-left">${button('标签','tag-filter','ghost','Tag')}${button('最近修改','note-sort','ghost','ChevronDown')}</div>${button('管理分组','groups','ghost','Folder')}</div><div class="mobile-page-search">${searchField('搜索笔记')}</div>${ns.map(n=>`<div class="content-row"><div class="object-icon">${icon('FileText')}</div><button class="row-open" data-note="${n.id}"><strong>${esc(n.title)}</strong><p>${esc(n.body.replace(/<[^>]*>/g,' ').slice(0,65))}</p><div class="row-meta"><span>${esc(n.group)}</span><span>·</span><span>${esc(n.updated)}</span></div></button>${ib('MoreHorizontal','笔记选项','note-more:'+n.id,'reveal')}</div>`).join('')||empty(filter?'没有找到相关笔记':'还没有笔记',filter?'清除搜索，或换一个关键词。':'从一个问题，或一句自己的话开始。',filter?'clear-search':'new-note',filter?'清除搜索':'新建笔记')}</div>`;}
function note(){const n=data.notes.find(n=>n.id===selectedNote)||data.notes[0];selectedNote=n.id;return `<article class="document ${data.wide?'wide-doc':''}"><div class="doc-top">${icon('FileText')}<span>${esc(n.group)}</span></div><label><span class="sr-only">笔记标题</span><textarea id="note-title" class="note-title" rows="1" ${readOnly()?'readonly':''}>${esc(n.title)}</textarea></label><div class="doc-meta"><span>个人笔记</span><span>·</span><span>${esc(n.updated)}</span><button class="chip" data-action="note-tags">添加标签</button></div><div class="doc-rule"></div><div id="note-body" class="prose" contenteditable="${!readOnly()}" role="textbox" aria-multiline="true" aria-label="笔记正文" style="font-family:${data.noteFont==='serif'?'Georgia, &quot;Songti SC&quot;, serif':data.noteFont==='mono'?'var(--fontMono)':'inherit'}">${sanitize(n.body)}</div><div class="inline-note-tools">${button('插入内容','insert-block','ghost','Plus')}${button('查看评论','comments','ghost','MessageSquare')}${button('版本记录','history','ghost','History')}</div></article>`;}
function reader(){const m=data.materials.find(m=>m.id===selectedArticle)||data.materials[0];const noBody=selectedArticle==='a2'||state==='empty';return `<article class="document"><div class="doc-top"><span>${esc(m.source)}</span><span>·</span><span>${esc(m.meta)}</span></div><h1>${esc(m.title)}</h1><div class="doc-meta"><span class="chip">${esc(m.status||'未读')}</span><span>${esc(m.tag||'阅读')}</span><span>10 月 15 日保存</span></div>${tabs([['original','正文'],['digest','整理稿']],window.readerMode||'original','reader-mode')}${noBody?empty('暂时没有文章正文','链接已保留。可以稍后重新获取正文，也可以留下自己的阅读记录。','retry-body','重新获取正文'):window.readerMode==='digest'?`<div class="prose"><p>这篇文章讨论了注意力与日常工作方式的关系。</p><h2>值得留下的三个想法</h2><ul><li>减少切换，给当前任务留出连续时间。</li><li>建立一个可靠的收集入口，把整理留给专门的时间。</li><li>区分收集与理解，阅读后用自己的话留下一句判断。</li></ul><p class="muted">整理稿是个人理解的起点，可以继续修改和补充。</p></div>${button('保存为笔记','digest-save','outline','FileText')}`:`<div class="prose"><p>每天都会有新的信息到来。值得读的文章、突然出现的想法、还没有完成的小事，常常一起占据我们的注意力。</p><p>问题不在于把每一件事都做得更快，而在于为重要的事情留下足够完整的时间。</p><h2>给信息一个入口</h2><p>一个可靠的收集入口，可以帮助我们暂时放下“不能忘记”的担忧。当想法有了去处，注意力就能回到眼前的事情。</p><p><mark>保存不是理解。真正的理解，发生在我们愿意停下来，用自己的话重新表达的时候。</mark></p><h2>少一点切换，多一点连续</h2><p>把相近的事情放在一起，把需要思考的事情留给完整的时间。简单的边界，会逐渐成为一种轻松的日常节奏。</p><blockquote>留白不是空缺，而是让下一步有机会自然发生。</blockquote><h2>把读到的，变成自己的</h2><p>读完之后，不必急着写一篇完整的总结。先留下一个问题、一句判断，或者一个可以实践的小行动。</p><p>知识不只停留在资料库里，也会在行动和回顾中，慢慢变成我们的一部分。</p></div><div class="inline-note-tools">${button('查看高亮','highlights','ghost','FileText')}${button('标记已读','mark-read','outline','Check')}</div>`}</article>`;}
function tasks(){const t=data.tasks.find(t=>t.id===selectedTask);const list=filtered(data.tasks).filter(t=>taskScope==='done'?t.done:taskScope==='work'?t.list==='工作':!t.done);return `<div class="page"><div class="page-head"><h1>待办</h1><div class="head-actions">${searchField('搜索待办')}${button('添加任务','new-task','primary','Plus')}</div></div>${tabs([['list','清单'],['calendar','日历'],['countdown','倒数日'],['lessons','经验']],taskTab,'task-tab')}<div class="mobile-page-search">${searchField('搜索待办')}</div>${taskTab==='calendar'?calendar():taskTab==='countdown'?countdowns():taskTab==='lessons'?lessons():`<div class="task-layout ${t?'has-detail':''}"><div class="task-list"><div class="toolbar"><div class="scope-select">${[['all','全部待办'],['work','工作'],['done','已完成']].map(([id,label])=>`<button class="${taskScope===id?'active':''}" data-scope="${id}">${label}</button>`).join('')}</div>${ib('SlidersHorizontal','筛选任务','task-filter')}</div><p class="task-group">${taskScope==='done'?'已完成':taskScope==='work'?'工作清单':'接下来的安排'}</p>${taskRows(list)||empty('这里暂时没有任务','从一件可以完成的小事开始。','new-task','添加任务')}<button class="task-add" data-action="new-task">${icon('Plus')}添加任务</button></div>${t?`<aside class="task-detail" aria-label="任务详情"><div class="panel-head"><span class="muted">任务详情</span>${ib('X','关闭详情','task-close')}</div><h2 class="detail-title">${esc(t.title)}</h2><div class="property-row"><span>所在清单</span><button class="chip" data-action="task-list">${esc(t.list)}</button></div><div class="property-row"><span>截止日期</span><button class="chip" data-action="task-date">${esc(t.date)}</button></div><div class="property-row"><span>优先级</span><button class="chip" data-action="task-priority">普通</button></div><p class="detail-note">${esc(t.note)}</p>${button(t.done?'重新打开任务':'完成任务','complete-selected','primary','Check')}<div class="inline-note-tools">${button('添加子任务','subtask','ghost','Plus')}${button('更多','task-more','ghost','MoreHorizontal')}</div></aside>`:''}</div>`}</div>`;}
function calendar(){return `<div class="toolbar"><span class="muted">2026 年 10 月</span>${button('选择日期','pick-date','outline','Calendar')}</div><div class="calendar-grid" aria-label="十月日历">${Array.from({length:28},(_,i)=>`<button class="cal-day ${i===14?'today':''}" data-day="${i+1}" aria-label="10月${i+1}日，添加任务">${i+1}${[14,16,20].includes(i)?`<span class="cal-event">${esc(data.tasks[i%data.tasks.length].title)}</span>`:''}</button>`).join('')}</div>`;}
function countdowns(){return `<div class="section-head"><p class="muted">值得期待的日子</p>${button('新建倒数日','new-countdown','outline','Plus')}</div><div class="content-row"><div class="stat"><strong>16</strong></div><div class="row-open"><strong>秋日徒步</strong><p>10 月 31 日，星期六</p></div>${ib('MoreHorizontal','编辑倒数日','countdown-edit')}</div>`;}
function lessons(){return `<div class="section-head"><p class="muted">从行动中留下的经验</p>${button('记录经验','new-lesson','outline','Plus')}</div><div class="content-row"><div class="object-icon">${icon('FileText')}</div><button class="row-open" data-action="lesson-open"><strong>先做一个小的下一步</strong><p>把“整理资料”缩小成“给三篇文章各写一句判断”，更容易开始。</p><div class="row-meta">个人 · 10 月 13 日</div></button>${icon('ChevronRight')}</div>`;}
function canvas(){return `<div class="canvas-page"><div class="canvas-titlebar"><div><h1>一场慢一点的旅行</h1><span class="readonly-note">手机预览 · 可缩放和查看内容</span></div><div class="inline">${button('添加内容','canvas-add','outline','Plus')}${ib('MoreHorizontal','画布选项','canvas-more')}</div></div><div class="canvas-stage" id="canvas-stage"><div class="canvas-world" id="canvas-world" style="transform:scale(${zoom/100})"><div class="canvas-board"><h2>走出去，再慢一点。</h2><p>这个秋天，留一个周末给自己。</p><div class="canvas-grid"><button class="canvas-card" data-action="canvas-route"><div class="canvas-landscape" role="img" aria-label="山形几何示意"></div><h3>沿着山脊走一段</h3><p>不追求速度，给沿途的风景留出时间。</p><small>路线想法 · 来自资料库</small></button><button class="canvas-card" data-action="canvas-thought"><h3>想留下的感觉</h3><p>轻装、慢走、留白。<br><br>把手机放回口袋，让视线离开屏幕。</p><small>随手记下</small></button><button class="canvas-card" data-note="n2" style="grid-column:1/-1"><h3>行前准备</h3><p>水和外套 / 查看天气 / 提前规划返程</p><small>关联笔记 · 秋日徒步路线</small></button></div></div><div class="canvas-connector"></div><div class="canvas-sticky"><h3>下一个小行动</h3><p>先把这一天空出来。</p><ul><li>选一个晴天</li><li>邀请一位朋友</li><li>带上好奇心</li></ul>${button('查看相关任务','go-tasks','ghost','ArrowRight')}</div></div></div><div class="canvas-bottom">${ib('Minus','缩小画布','zoom-out')}<span aria-live="polite">${zoom}%</span>${ib('Plus','放大画布','zoom-in')}${ib('Maximize','适应画布','zoom-fit')}</div></div>`;}
function settings(){const nav=[['appearance','外观'],['editor','阅读与编辑'],['data','数据与备份'],['ai','AI 服务'],['plugins','插件'],['account','账户']];let content='';if(settingTab==='appearance')content=`<h2>外观</h2><p>让工作区适合你的习惯。</p><div class="setting-row"><div><h3>主题</h3><p>浅色、暗色，或跟随设备设置。</p></div><div class="segmented">${[['light','浅色'],['dark','暗色'],['system','跟随系统']].map(([id,label])=>`<button data-theme-mode="${id}" class="${data.theme===id?'active':''}" aria-pressed="${data.theme===id}">${label}</button>`).join('')}</div></div><div class="setting-row"><div><h3>列表密度</h3><p>调整列表中的信息间距。</p></div><div class="segmented">${[['regular','舒适'],['compact','紧凑']].map(([id,label])=>`<button data-density="${id}" class="${data.density===id?'active':''}" aria-pressed="${data.density===id}">${label}</button>`).join('')}</div></div><div class="setting-row"><div><h3>减少动态效果</h3><p>工作区会尊重设备的减少动态效果设置。</p></div><span class="chip">跟随系统</span></div>`;
 if(settingTab==='editor')content=`<h2>阅读与编辑</h2><p>偏好会保留在你的工作区。</p><div class="setting-row"><div><h3>笔记默认字体</h3><p>已有笔记可继续使用自己的设置。</p></div><select id="note-font" aria-label="笔记默认字体">${[['default','默认'],['serif','衬线'],['mono','等宽']].map(([id,label])=>`<option value="${id}" ${data.noteFont===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="setting-row"><div><h3>全宽显示笔记</h3><p>给复杂内容更多横向空间。</p></div><button class="toggle" role="switch" aria-checked="${data.wide}" aria-label="全宽显示笔记" data-action="toggle-wide"></button></div>${button('打开笔记查看','open-first-note','outline','FileText')}`;
 if(settingTab==='data')content=`<h2>数据与备份</h2><p>为留下的资料保留一份副本。</p><div class="setting-row"><div><h3>导出预览资料</h3><p>下载此浏览器内的演示记录。</p></div>${button('导出','export','outline','Download')}</div><div class="setting-row"><div><h3>重新开始预览</h3><p>清除本地演示记录，恢复初始内容。</p></div>${button('重置','reset','outline')}</div>`;
 if(settingTab==='ai')content=`<h2>AI 服务</h2><p>连接服务后，可以整理资料、提取重点。</p><div class="state-banner readonly">此设计预览不连接外部服务，不接收真实密钥。</div><div class="form-field"><label for="ai-endpoint">服务地址</label><input id="ai-endpoint" value="https://api.example.com/v1" readonly></div><div class="form-field"><label for="ai-model">模型</label><input id="ai-model" value="由你的服务提供" readonly></div>${button('查看配置说明','ai-help','outline')}`;
 if(settingTab==='plugins')content=`<h2>插件</h2><p>为工作区增加恰好需要的能力。</p>${[['summary','AI 摘要','提炼长文的关键内容。'],['tags','标签推荐','为资料建议相关标签。']].map(([id,name,desc])=>`<div class="setting-row"><div><h3>${name}</h3><p>${desc}</p></div><button class="toggle" role="switch" aria-checked="${Boolean(data['plugin_'+id])}" aria-label="启用${name}" data-plugin="${id}"></button></div>`).join('')}`;
 if(settingTab==='account')content=`<h2>账户</h2><p>我的空间</p><div class="setting-row"><div><h3>个人资料</h3><p>当前为离线设计预览，没有登录真实账户。</p></div><span class="avatar">K</span></div><div class="setting-row"><div><h3>关于 Cairn</h3><p>为值得留下的资料、想法和行动，找到一个去处。</p></div>${button('查看设计说明','about','outline')}</div>`;
 return `<div class="page"><div class="page-head"><h1>设置</h1>${searchField('搜索设置')}</div><div class="settings-layout"><nav class="settings-nav" aria-label="设置分区">${nav.filter(([id,label])=>!filter||label.includes(filter)).map(([id,label])=>`<button data-setting="${id}" class="${settingTab===id?'active':''}">${label}</button>`).join('')}</nav><section class="settings-section">${content}</section></div></div>`;}
function favorites(){return `<div class="page"><div class="page-head"><h1>收藏夹</h1>${searchField('搜索收藏')}</div>${materialRows(filtered(data.materials.filter(m=>data.favorites.includes(m.id))))||empty('还没有收藏','遇到想常常回看的资料，可以点一下收藏。','go-library','打开资料库')}</div>`;}
function render(){renderSidebar();renderTop();renderBanner();shell.classList.toggle('compact',data.density==='compact');$('#main').innerHTML=({home,library,notes,note,reader,tasks,canvas,settings,favorites,trash:()=>`<div class="page"><div class="page-head"><h1>垃圾箱</h1></div>${empty('垃圾箱是空的','移入垃圾箱的内容会在这里保留，以便恢复。','go-library','返回资料库')}</div>`}[page]||home)();renderBottom();if(drawer)openDrawer();}
function renderBottom(){const b=$('#bottom-nav');b.classList.toggle('context-active',page==='reader'||page==='note');b.innerHTML=page==='reader'?`<button data-action="highlights">${icon('FileText')}高亮</button><button data-action="reader-progress">${icon('Clock')}进度 38%</button><button data-action="page-more">${icon('MoreHorizontal')}更多</button>`:page==='note'?`<button data-action="insert-block">${icon('Plus')}插入</button><button data-action="comments">${icon('MessageSquare')}评论</button><button data-action="history">${icon('History')}版本</button>`:'';}
function openModal(html,cls=''){closeDrawer();lastFocus=document.activeElement;modal.className=cls;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();requestAnimationFrame(()=>{const el=$('[autofocus]',modal)||$('input,textarea,button',modal);el?.focus();});}
function closeModal(){modal.close();}
modal.addEventListener('close',()=>{modal.className='';if(lastFocus?.isConnected)lastFocus.focus();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function modalHead(title){return `<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${ib('X','关闭','modal-close')}</div>`;}
function info(title,body,footer=''){openModal(`<div class="modal-inner">${modalHead(title)}<div class="modal-intro">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div>`);}
function menu(title,items){openModal(`${modalHead(title)}<div class="menu-list">${items.map(x=>x===null?'<div class="menu-separator"></div>':`<button class="menu-item ${x[3]||''}" data-action="${x[1]}">${x[2]?icon(x[2]):''}${esc(x[0])}</button>`).join('')}</div>`,'menu-dialog');}
function composerModal(type='memo',preset=''){const labels={memo:'留下一个想法',note:'新建笔记',task:'添加任务',collection:'新建集合',countdown:'新建倒数日',lesson:'记录经验'};openModal(`<form class="modal-inner" id="new-form" data-type="${type}">${modalHead(labels[type]||'添加资料')}<div class="form-field"><label for="new-title">${type==='memo'?'内容':type==='collection'?'集合名称':type==='task'?'要做什么':'标题'}</label>${type==='memo'?`<textarea id="new-title" autofocus required placeholder="不必完整，先写下来…">${esc(preset)}</textarea>`:`<input id="new-title" autofocus required placeholder="${type==='task'?'一个具体、可以开始的小行动':'起一个清楚的名字'}" value="${esc(preset)}" autocomplete="off">`}</div>${type==='task'||type==='countdown'?'<div class="form-field"><label for="new-date">日期</label><input id="new-date" type="date" value="2026-10-15"></div>':''}${type==='collection'?'<div class="form-field"><label for="new-desc">简介</label><input id="new-desc" placeholder="围绕什么问题收集资料？"></div>':''}<p class="field-error" id="new-error" role="alert"></p><div class="modal-footer">${button('取消','modal-close','ghost')}<button class="btn primary" type="submit">${type==='memo'?'保存':'创建'}</button></div></form>`);}
function openSearch(){openModal(`<div><h2 id="modal-title" class="sr-only">搜索全部内容</h2><div class="command-search">${icon('Search')}<input id="command-input" autofocus placeholder="搜索资料、笔记和待办…" aria-label="搜索全部内容">${ib('X','关闭搜索','modal-close')}</div><div id="command-results" class="command-results"></div><div class="command-footer">↑ ↓ 选择　Enter 打开　Esc 关闭</div></div>`);renderSearch('');}
function renderSearch(query){const navs=[['工作台','home','Home'],['资料库','library','Library'],['笔记','notes','FileText'],['待办','tasks','ListChecks'],['构思画布','canvas','LayoutGrid'],['设置','settings','Settings']];const match=s=>s.toLowerCase().includes(query.toLowerCase());let html=navs.filter(n=>match(n[0])).map(([name,pg,ico])=>`<button class="command-item" data-page="${pg}">${icon(ico)}${name}<small>页面</small></button>`).join('');html+=data.notes.filter(n=>match(n.title)).map(n=>`<button class="command-item" data-note="${n.id}">${icon('FileText')}${esc(n.title)}<small>笔记</small></button>`).join('');html+=data.materials.filter(n=>match(n.title)).map(n=>`<button class="command-item" data-material="${n.id}">${icon(n.type==='files'?'File':'Link')}${esc(n.title.slice(0,35))}<small>${n.source}</small></button>`).join('');html+=data.tasks.filter(n=>match(n.title)).map(n=>`<button class="command-item" data-task="${n.id}">${icon('ListChecks')}${esc(n.title)}<small>待办</small></button>`).join('');$('#command-results').innerHTML=html||'<div class="empty"><div><h2>没有找到相关内容</h2><p>试试其他关键词。</p></div></div>';}
function openDrawer(){if(!isMobile())return;lastFocus=document.activeElement;drawer=true;$('#sidebar').classList.add('drawer-open');$('#drawer-mask').classList.add('open');$('.workspace').inert=true;requestAnimationFrame(()=>$('.drawer-close')?.focus());}
function closeDrawer(){drawer=false;$('#sidebar').classList.remove('drawer-open');$('#drawer-mask').classList.remove('open');$('.workspace').inert=false;if(lastFocus?.isConnected&&lastFocus.closest('.topbar'))lastFocus.focus();}
function openMaterial(id){const m=data.materials.find(m=>m.id===id);if(!m)return;if(m.type==='reading'){window.readerMode='original';navigate('reader',{article:id});}else if(m.type==='memos'){info('速记',`<p>${esc(m.title)}</p><p style="margin-top:16px;color:var(--secondary)">#${esc(m.tag||'随想')} · ${esc(m.meta)}</p>`,button('转为笔记','memo-to-note:'+id,'outline','FileText'));}else{info(m.title,`<p>${esc(m.source)} · ${esc(m.meta)}</p><p style="margin-top:16px">文件信息已保存在资料库。本预览只展示文件信息，不包含原始附件内容。</p>`,button('关闭','modal-close','outline'));}}
function saveNew(type,title,desc='',date='今天'){const id='local'+Date.now();if(type==='note'){data.notes.unshift({id,title,group:'未分组',updated:'刚刚',body:'<p>从这里继续写下去。</p>'});saveFeedback();navigate('note',{note:id});}else if(type==='task'){data.tasks.unshift({id,title,list:'个人',date:date==='2026-10-15'?'今天':date||'未设日期',done:false,note:'',sub:''});saveFeedback();render();}else if(type==='collection'){data.collections.unshift({id,title,desc,count:0});saveFeedback();libTab='collections';navigate('library',{libTab:'collections'});}else if(type==='memo'){data.materials.unshift({id,type:'memos',title,source:'速记',meta:'刚刚',tag:'随想',status:'',desc:''});saveFeedback();if(page!=='home'){libTab='memos';render();}else render();}else if(type==='countdown'){data.countdown={title,date};saveFeedback();taskTab='countdown';navigate('tasks');}else{data.lesson={title,desc};saveFeedback();taskTab='lessons';navigate('tasks');}}
function recordCapture(text,type){if(/^https?:\/\//i.test(text)){const id='a'+Date.now();let host='网页';try{host=new URL(text).hostname;}catch{}data.materials.unshift({id,type:'reading',title:text,source:host,meta:'链接',tag:'',status:'未读',desc:'仅保留链接，稍后可以获取正文。'});saveFeedback();render();return;}saveNew(type==='memo'?'memo':type,text);}
function updateNote(){const n=data.notes.find(n=>n.id===selectedNote);if(!n||readOnly())return;const title=$('#note-title'),body=$('#note-body');if(title)n.title=title.value||'无标题';if(body)n.body=sanitize(body.innerHTML);n.updated='刚刚';noteStatus='saving';renderTop();clearTimeout(noteTimer);noteTimer=setTimeout(()=>{persist();noteStatus=storageFailed?'error':'saved';renderTop();renderBanner();noteTimer=null;},650);}
function exportData(){flushNote();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cairn-preview-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出预览资料');}
function choose(title,items,key){menu(title,items.map(x=>[x,key+':'+x,'Check']));}
function pageMore(){if(page==='note')menu('笔记选项',[['版本记录','history','History'],['评论','comments','MessageSquare'],['字体与宽度','note-appearance','Settings'],['移动到分组','move-note','Folder'],['导出此笔记','export-note','Download'],null,['移入垃圾箱','delete-note:'+selectedNote,'Trash2','danger']]);else if(page==='reader')menu('文章选项',[['查看高亮','highlights','FileText'],['查看整理稿','show-digest','FileText'],['保存到笔记','digest-save','FileText'],['标记已读','mark-read','Check'],['收藏文章','favorite','Star']]);else menu('更多选项',[['搜索全部内容','search','Search'],['添加资料','new','Plus'],['打开设置','go-settings','Settings'],['关于此预览','about','FileText']]);}
function perform(action){
 const [key,...parts]=action.split(':');const arg=parts.join(':');
 const mutations=['new-note','new-task','new-collection','new-countdown','new-lesson','new','delete-note','delete-material','complete-selected','favorite','mark-read','memo-to-note','digest-save','collection-add','file-import','task-date','task-list','task-priority','insert-block','subtask','canvas-add','note-tags','move-note','restore-version'];
 if(readOnly()&&mutations.includes(key)){toast('当前内容为只读，可以查看和复制。');return;}
 switch(key){
 case 'drawer-open':openDrawer();break;case 'drawer-close':closeDrawer();break;case 'modal-close':closeModal();break;case 'search':openSearch();break;
 case 'back':navigate(page==='note'?'notes':'library');break;
 case 'new':menu('新建',[['添加链接或速记','new-memo','Plus'],['新建笔记','new-note','FileText'],['添加任务','new-task','ListChecks'],['导入文件','file-import','File']]);break;
 case 'new-memo':composerModal('memo');break;case 'new-note':composerModal('note');break;case 'new-task':composerModal('task');break;case 'new-collection':composerModal('collection');break;case 'new-countdown':composerModal('countdown');break;case 'new-lesson':composerModal('lesson');break;
 case 'page-more':pageMore();break;case 'account':menu('我的空间',[['账户设置','account-settings','Settings'],['外观','appearance-settings','Sun'],['关于此预览','about','FileText']]);break;
 case 'go-tasks':case 'go-library':case 'go-settings':if(modal.open)closeModal();navigate(key.split('-')[1]);break;
 case 'account-settings':case 'appearance-settings':closeModal();settingTab=key==='account-settings'?'account':'appearance';navigate('settings');break;
 case 'open-first-note':if(modal.open)closeModal();navigate('note',{note:data.notes[0].id});break;case 'open-first-article':navigate('reader',{article:'a1'});break;
 case 'clear-search':filter='';render();break;case 'focus-capture':$('#capture-input')?.focus();break;
 case 'normal':state='normal';$('#state-select').value='normal';render();toast('已恢复正常状态');break;
 case 'resolve':info('比较版本','<p>你在这里留下的内容，和另一处的新版本都已保留。选择后再继续编辑。</p><div class="panel-item"><h3>此设备</h3><p>保留本次编辑的文字与段落。</p></div><div class="panel-item"><h3>另一处</h3><p>标题和部分正文有所更新。</p></div>',button('保留本机内容','resolve-local','primary')+button('查看另一版本','resolve-remote','outline'));break;
 case 'resolve-local':closeModal();state='normal';$('#state-select').value='normal';persist();render();toast('已选择保留本机内容');break;
 case 'resolve-remote':info('另一版本','<p>此为冲突演示中的另一版本。你的本机内容仍然保留，不会被自动覆盖。</p>',button('返回比较','resolve','outline'));break;
 case 'tag-filter':choose('按标签筛选',['全部','思考','设计','生活','工作'],'filter-tag');break;
 case 'filter-tag':closeModal();filter=arg==='全部'?'':arg;render();break;
 case 'sort':data.materials.reverse();closeModal();persist();render();toast('已切换资料排序');break;case 'note-sort':data.notes.reverse();persist();render();toast('已切换笔记排序');break;
 case 'groups':choose('管理笔记分组',['个人思考','工作','生活','未分组'],'select-group');break;case 'select-group':closeModal();groupFilter=arg;render();break;
 case 'material-more':menu('资料选项',[['打开资料','open-material:'+arg,'FileText'],['加入集合','add-material-collection:'+arg,'Folder'],['收藏 / 取消收藏','favorite-material:'+arg,'Star'],null,['移入垃圾箱','delete-material:'+arg,'Trash2','danger']]);break;
 case 'open-material':closeModal();openMaterial(arg);break;
 case 'add-material-collection':choose('加入集合',data.collections.map(c=>c.title),'add-collection-choice');break;
 case 'add-collection-choice':{const c=data.collections.find(c=>c.title===arg);if(c)c.count++;persist();closeModal();toast('已加入集合');break;}
 case 'favorite-material':{const i=data.favorites.indexOf(arg);if(i>=0)data.favorites.splice(i,1);else data.favorites.push(arg);persist();closeModal();render();toast(i>=0?'已取消收藏':'已收藏');break;}
 case 'favorite':{const i=data.favorites.indexOf(selectedArticle);if(i>=0)data.favorites.splice(i,1);else data.favorites.push(selectedArticle);persist();if(modal.open)closeModal();toast(i>=0?'已取消收藏':'已收藏');break;}
 case 'note-more':selectedNote=arg;menu('笔记选项',[['打开笔记','open-note:'+arg,'FileText'],['移动到分组','move-note','Folder'],['版本记录','history','History'],null,['移入垃圾箱','delete-note:'+arg,'Trash2','danger']]);break;
 case 'open-note':closeModal();navigate('note',{note:arg});break;
 case 'delete-note':case 'delete-material':info('移入垃圾箱','内容可以在垃圾箱中恢复。',button('取消','modal-close','ghost')+button('移入垃圾箱','confirm-delete:'+key+':'+arg,'outline','Trash2'));break;
 case 'confirm-delete':{const [kind,id]=parts;const source=kind==='delete-note'?data.notes:data.materials;const idx=source.findIndex(x=>x.id===id);if(idx>=0){data.deleted=data.deleted||[];data.deleted.push({kind,item:source.splice(idx,1)[0]});}persist();closeModal();navigate(kind==='delete-note'?'notes':'library');toast('已移入垃圾箱');break;}
 case 'restore':{const idx=Number(arg),entry=data.deleted?.[idx];if(entry){(entry.kind==='delete-note'?data.notes:data.materials).unshift(entry.item);data.deleted.splice(idx,1);persist();render();toast('已恢复');}break;}
 case 'memo-to-note':{const m=data.materials.find(m=>m.id===arg);if(m){closeModal();const id='n'+Date.now();data.notes.unshift({id,title:m.title.slice(0,20),group:'未分组',updated:'刚刚',body:'<p>'+esc(m.title)+'</p>'});persist();navigate('note',{note:id});toast('已转为笔记');}break;}
 case 'move-note':choose('移动到分组',['个人思考','工作','生活','未分组'],'move-note-choice');break;
 case 'move-note-choice':{const n=data.notes.find(n=>n.id===selectedNote);if(n)n.group=arg;persist();closeModal();render();toast('已移动到'+arg);break;}
 case 'history':{const n=data.notes.find(n=>n.id===selectedNote);info('版本记录',`<div class="panel-item"><h3>刚刚 · 当前版本</h3><p>${esc(n?.title||'笔记')}</p><p>当前内容已保存在此浏览器。</p></div><div class="panel-item"><h3>今天 09:30</h3><p>上一次留下的版本</p>${button('预览此版本','preview-version','outline')}</div>`);break;}
 case 'preview-version':{const n=initial.notes.find(n=>n.id===selectedNote)||initial.notes[0];info('历史版本 · 今天 09:30',`<h3>${esc(n.title)}</h3><div class="prose" style="font-size:14px;margin-top:20px">${n.body}</div>`,button('返回版本列表','history','ghost')+button('恢复此版本','restore-version','outline'));break;}
 case 'restore-version':{const n=data.notes.find(n=>n.id===selectedNote),old=initial.notes.find(n=>n.id===selectedNote)||initial.notes[0];if(n)n.body=old.body;persist();closeModal();render();toast('已恢复历史版本');break;}
 case 'comments':info('评论',`<div class="panel-item"><h3>我的空间</h3><p>“每次阅读，留下一句自己的判断。”这一步可以先从今天开始。</p><small>今天 10:35</small></div>${(data.comments||[]).map(c=>`<div class="panel-item"><h3>我</h3><p>${esc(c)}</p><small>刚刚</small></div>`).join('')}<form id="comment-form"><div class="form-field"><label for="comment-input">留下评论</label><textarea id="comment-input" placeholder="写下你的想法…" ${readOnly()?'disabled':''}></textarea></div><div class="modal-footer"><button type="submit" class="btn primary" ${readOnly()?'disabled':''}>发送评论</button></div></form>`);break;
 case 'insert-block':menu('插入内容',[['小标题','insert-heading','FileText'],['段落','insert-paragraph','FileText'],['项目列表','insert-list','ListChecks']]);break;
 case 'insert-heading':case 'insert-paragraph':case 'insert-list':closeModal();{const body=$('#note-body');if(body){body.insertAdjacentHTML('beforeend',key==='insert-heading'?'<h2>新的小标题</h2>':key==='insert-list'?'<ul><li>新的要点</li></ul>':'<p>在这里继续写…</p>');body.focus();updateNote();body.lastElementChild?.scrollIntoView({block:'nearest'});}}break;
 case 'note-tags':choose('添加标签',['思考','工作','生活','阅读'],'note-tag-choice');break;
 case 'note-tag-choice':{const n=data.notes.find(n=>n.id===selectedNote);if(n)n.tag=arg;persist();closeModal();toast('已添加标签：'+arg);break;}
 case 'note-appearance':menu('笔记显示',[['默认字体','font:default','FileText'],['衬线字体','font:serif','FileText'],['等宽字体','font:mono','FileText'],[data.wide?'恢复标准宽度':'全宽显示','toggle-wide','LayoutGrid']]);break;
 case 'font':data.noteFont=arg;persist();closeModal();render();break;
 case 'toggle-wide':data.wide=!data.wide;persist();if(modal.open)closeModal();render();break;
 case 'export':exportData();break;case 'export-note':{const n=data.notes.find(n=>n.id===selectedNote);info('复制笔记',`<div class="form-field"><label for="copy-note">笔记内容</label><textarea id="copy-note" rows="10" readonly>${esc(n?.title+'\n\n'+(n?.body||'').replace(/<[^>]*>/g,' '))}</textarea></div>`,button('选中全部','select-note-text','outline'));break;}
 case 'select-note-text':$('#copy-note').select();break;
 case 'show-digest':if(modal.open)closeModal();window.readerMode='digest';render();break;
 case 'digest-save':{const id='n'+Date.now();data.notes.unshift({id,title:'阅读整理 · 把注意力还给重要的事',group:'个人思考',updated:'刚刚',body:'<p>整理后，留下一句自己的判断。</p><h2>三个想法</h2><ul><li>减少切换，留出连续时间。</li><li>建立一个可靠的收集入口。</li><li>把阅读变成自己的表达。</li></ul>'});persist();if(modal.open)closeModal();navigate('note',{note:id});toast('已保存为笔记');break;}
 case 'mark-read':{const m=data.materials.find(m=>m.id===selectedArticle);if(m)m.status='已读';persist();if(modal.open)closeModal();render();toast('已标记为已读');break;}
 case 'highlights':info('文章高亮','<div class="panel-item"><p>保存不是理解。真正的理解，发生在我们愿意停下来，用自己的话重新表达的时候。</p><small>正文 · 第二节</small></div>',button('返回正文','close-highlights','outline'));break;
 case 'close-highlights':closeModal();$('.prose mark')?.scrollIntoView({block:'center',behavior:'smooth'});break;
 case 'reader-progress':info('阅读进度','<p>已读 38%，大约还需要 5 分钟。</p>',button('继续阅读','modal-close','primary'));break;
 case 'retry-body':info('正文暂时无法获取','<p>链接已保留，可以稍后再试。也可以先把自己的想法记下来。</p>',button('记下想法','new-note','outline'));break;
 case 'task-close':selectedTask=null;render();break;case 'complete-selected':{const t=data.tasks.find(t=>t.id===selectedTask);if(t)t.done=!t.done;persist();render();toast(t?.done?'任务已完成':'任务已重新打开');break;}
 case 'task-filter':choose('显示任务',['全部待办','工作','已完成'],'task-filter-choice');break;
 case 'task-filter-choice':taskScope=arg==='工作'?'work':arg==='已完成'?'done':'all';closeModal();render();break;
 case 'task-list':choose('移到清单',['个人','工作','生活'],'task-list-choice');break;
 case 'task-list-choice':{const t=data.tasks.find(t=>t.id===selectedTask);if(t)t.list=arg;persist();closeModal();render();break;}
 case 'task-date':openDate('任务日期','task-date-form');break;
 case 'pick-date':openDate('选择日期','review-date-form');break;
 case 'task-priority':choose('任务优先级',['普通','重要','紧急'],'task-priority-choice');break;
 case 'task-priority-choice':{const t=data.tasks.find(t=>t.id===selectedTask);if(t)t.priority=arg;persist();closeModal();toast('优先级已设为'+arg);break;}
 case 'subtask':composerModal('task','');break;
 case 'task-more':menu('任务选项',[['更改日期','task-date','Calendar'],['移到清单','task-list','Folder'],['添加子任务','subtask','Plus']]);break;
 case 'countdown-edit':composerModal('countdown',data.countdown?.title||'秋日徒步');break;
 case 'lesson-open':info(data.lesson?.title||'先做一个小的下一步','<p>把抽象的目标缩小到一个可以立即开始的行动。让任务更具体，开始就变得容易。</p>',button('记录新经验','new-lesson','outline'));break;
 case 'collection-back':selectedCollection=null;libTab='collections';render();break;
 case 'collection-add':info('添加资料',`<div>${data.materials.slice(0,4).map(m=>`<button class="command-item" data-action="add-existing:${m.id}">${icon('Plus')}${esc(m.title.slice(0,28))}</button>`).join('')}</div>`);break;
 case 'add-existing':{const c=data.collections.find(c=>c.id===selectedCollection);if(c)c.count++;persist();closeModal();render();toast('已添加到集合');break;}
 case 'collection-digest':info('集合整理稿','<p>将相关资料的共同主题、不同观点和下一步行动放在一起。</p><h3 style="margin-top:20px">共同主题</h3><p>为注意力留出空间，让收集慢慢转化为理解。</p>',button('保存为笔记','digest-save','outline'));break;
 case 'collection-more':menu('集合选项',[['打开集合','open-collection:'+arg,'Folder'],['添加资料','collection-add','Plus']]);selectedCollection=arg;break;
 case 'open-collection':closeModal();navigate('library',{libTab:'collections',collection:arg});break;
 case 'file-import':openModal(`<form class="modal-inner" id="file-form">${modalHead('导入文件')}<p class="modal-intro">选择一个文件，加入当前资料库。预览仅保留文件名和大小。</p><div class="form-field"><label for="import-file">选择文件</label><input id="import-file" type="file" required></div><div class="modal-footer"><button class="btn primary" type="submit">导入</button></div></form>`);break;
 case 'canvas-add':if(isMobile()){toast('手机仅支持查看画布');break;}composerModal('memo');break;
 case 'canvas-more':menu('画布选项',[['适应画布','zoom-fit','Maximize'],['关联资料','go-library','Library'],['打开相关笔记','open-first-note','FileText']]);break;
 case 'canvas-route':info('沿着山脊走一段','<p>不追求速度，给沿途的风景留出时间。</p><p style="margin-top:12px">来源：城市漫步集合</p>',button('打开集合','open-collection:c2','outline'));break;
 case 'canvas-thought':info('想留下的感觉','<p>轻装、慢走、留白。</p><p style="margin-top:12px">把手机放回口袋，让视线离开屏幕。</p>');break;
 case 'zoom-in':zoom=Math.min(120,zoom+10);render();break;case 'zoom-out':zoom=Math.max(30,zoom-10);render();break;case 'zoom-fit':zoom=isMobile()?38:80;if(modal.open)closeModal();render();break;
 case 'ai-help':info('AI 服务设置','<p>正式应用的服务地址、模型和密钥在设置中配置。密钥由服务端保管。</p><p style="margin-top:12px">此预览不发起网络请求，请不要在演示页面输入真实密钥。</p>');break;
 case 'reset':info('重新开始预览','<p>仅清除此浏览器中的演示记录，恢复初始内容。</p>',button('取消','modal-close','ghost')+button('重置演示资料','confirm-reset','outline'));break;
 case 'confirm-reset':data=structuredClone(initial);persist();setTheme('light');closeModal();navigate('home');toast('已恢复初始资料');break;
 case 'about':info('关于此设计预览','<p>Cairn 的跨端工作区提案，借鉴安静、中性的工具界面。具体颜色与布局为本项目设计参数，不是 Codex 内部设计规范。</p><p style="margin-top:12px">此处所有资料均为演示内容，只保存在此浏览器，不连接真实账号。</p>');break;
 case 'stats-range':choose('统计范围',['最近 7 天','最近 30 天','今年'],'stats-range-choice');break;
 case 'stats-range-choice':closeModal();toast('当前展示'+arg+'的演示统计');break;
 case 'stats-table':info('本周阅读明细','<table style="width:100%;text-align:left"><thead><tr><th>日期</th><th>阅读篇数</th></tr></thead><tbody>'+[2,4,3,5,2,6,4].map((x,i)=>`<tr><td>星期${['一','二','三','四','五','六','日'][i]}</td><td>${x}</td></tr>`).join('')+'</tbody></table>');break;
 default:toast('已打开'+key);
 }
}
function openDate(title,id){openModal(`<form class="modal-inner" id="${id}">${modalHead(title)}<div class="form-field"><label for="date-value">日期</label><input type="date" id="date-value" value="2026-10-15" required autofocus></div><div class="modal-footer"><button class="btn primary" type="submit">确定</button></div></form>`);}
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.action){e.preventDefault();perform(target.dataset.action);return;}if(target.dataset.page){e.preventDefault();if(modal.open)closeModal();navigate(target.dataset.page);return;}if(target.dataset.note){if(modal.open)closeModal();navigate('note',{note:target.dataset.note});return;}if(target.dataset.material){if(modal.open)closeModal();openMaterial(target.dataset.material);return;}if(target.dataset.collection){navigate('library',{libTab:'collections',collection:target.dataset.collection});return;}if(target.dataset.taskCheck){if(readOnly())return;const t=data.tasks.find(t=>t.id===target.dataset.taskCheck);if(t){t.done=!t.done;persist();render();toast(t.done?'任务已完成，可在已完成中重新打开':'已标为未完成');}return;}if(target.dataset.task){if(modal.open)closeModal();page='tasks';taskTab='list';selectedTask=target.dataset.task;render();return;}if(target.dataset.capture){captureType=target.dataset.capture;const text=$('#capture-input')?.value;const focus=$('#capture-input')===document.activeElement;render();if($('#capture-input'))$('#capture-input').value=text||'';if(focus)$('#capture-input').focus();return;}if(target.dataset.libTab){libTab=target.dataset.libTab;filter='';render();return;}if(target.dataset.homeTab){homeTab=target.dataset.homeTab;render();return;}if(target.dataset.taskTab){taskTab=target.dataset.taskTab;selectedTask=null;render();return;}if(target.dataset.readerMode){window.readerMode=target.dataset.readerMode;render();return;}if(target.dataset.readingFilter){readingFilter=target.dataset.readingFilter;render();return;}if(target.dataset.scope){taskScope=target.dataset.scope;render();return;}if(target.dataset.group){groupFilter=target.dataset.group;render();return;}if(target.dataset.setting){settingTab=target.dataset.setting;render();return;}if(target.dataset.themeMode){setTheme(target.dataset.themeMode);render();return;}if(target.dataset.density){data.density=target.dataset.density;persist();render();return;}if(target.dataset.plugin){data['plugin_'+target.dataset.plugin]=!data['plugin_'+target.dataset.plugin];persist();render();toast(data['plugin_'+target.dataset.plugin]?'已在预览中启用':'已在预览中停用');return;}if(target.dataset.day){openDate('10 月 '+target.dataset.day+' 日添加任务','calendar-date-form');$('#date-value').value='2026-10-'+target.dataset.day.padStart(2,'0');}});
document.addEventListener('compositionstart',()=>{composing=true;});document.addEventListener('compositionend',()=>{composing=false;});
document.addEventListener('input',e=>{if(e.target.matches('[data-page-search]')){filter=e.target.value;const pos=e.target.selectionStart;render();const input=$$('[data-page-search]').find(el=>el.offsetParent!==null);input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='command-input')renderSearch(e.target.value);if(e.target.id==='note-title'||e.target.closest('#note-body'))updateNote();});
