document.addEventListener('submit',e=>{e.preventDefault();if(composing||e.isComposing)return;const form=e.target;if(readOnly()&&form.id!=='review-date-form'){toast('当前内容为只读');return;}if(form.id==='capture-form'){const text=$('#capture-input').value.trim();if(!text){$('#capture-input').focus();return;}recordCapture(text,captureType);}if(form.id==='new-form'){const title=$('#new-title').value.trim();if(!title){$('#new-error').textContent='请先写下一点内容。';return;}const type=form.dataset.type,desc=$('#new-desc')?.value||'',date=$('#new-date')?.value||'今天';closeModal();if(type==='memo'&&/^https?:\/\//i.test(title))recordCapture(title,'memo');else saveNew(type,title,desc,date);}if(form.id==='comment-form'){const value=$('#comment-input').value.trim();if(!value)return;data.comments=data.comments||[];data.comments.push(value);persist();perform('comments');toast('评论已保存');}if(form.id==='file-form'){const file=$('#import-file').files[0];if(!file)return;data.materials.unshift({id:'f'+Date.now(),type:'files',title:file.name,source:file.type||'文件',meta:file.size>1024*1024?(file.size/1024/1024).toFixed(1)+' MB':Math.max(1,Math.round(file.size/1024))+' KB',tag:'',status:'',desc:'文件信息 · 刚刚'});persist();closeModal();navigate('library',{libTab:'files'});toast('已加入文件信息');}if(form.id==='task-date-form'){const t=data.tasks.find(t=>t.id===selectedTask);if(t)t.date=$('#date-value').value;persist();closeModal();render();}if(form.id==='review-date-form'){const date=$('#date-value').value;closeModal();toast('已选择 '+date);}if(form.id==='calendar-date-form'){const date=$('#date-value').value;composerModal('task');$('#new-date').value=date;}});
document.addEventListener('keydown',e=>{if(e.isComposing||composing||e.keyCode===229)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return;}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.id==='capture-input'){e.preventDefault();$('#capture-form').requestSubmit();return;}if(e.key==='Escape'&&drawer){e.preventDefault();closeDrawer();return;}if(drawer&&e.key==='Tab'){const buttons=$$('button,a,input', $('#sidebar')).filter(x=>!x.disabled&&x.offsetParent);const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ts=$$('[role=tab]',tab.parentElement);const idx=ts.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?ts.length-1:(idx+(e.key==='ArrowRight'?1:-1)+ts.length)%ts.length;ts[next].click();requestAnimationFrame(()=>{const groups=$$('[role=tablist]');const t=groups.find(g=>g.getAttribute('aria-label')===tab.parentElement.getAttribute('aria-label'));$$('[role=tab]',t||document).find(x=>x.getAttribute('aria-selected')==='true')?.focus();});}if(modal.open&&['ArrowDown','ArrowUp'].includes(e.key)&&$('#command-results')){e.preventDefault();const results=$$('.command-item',modal),idx=results.indexOf(document.activeElement);results[(idx+(e.key==='ArrowDown'?1:-1)+results.length)%results.length]?.focus();}if(modal.open&&e.key==='Enter'&&e.target.id==='command-input'){e.preventDefault();$('.command-item',modal)?.click();}});
